// Built-in asset library, generated by `npm run assets:sync`.
// Edit the source folder and re-run the script — don't hand-edit manifest.json.
import manifest from "./manifest.json";

export interface LibraryAsset {
  id: string;
  /** Slug of the top-level source folder, e.g. "app-screens", "mascots". */
  category: string;
  /** Subfolder path inside the category ("v1.2", "pre-review"), or "". */
  group: string;
  name: string;
  src: string;
  thumb: string;
  w: number;
  h: number;
}

export const LIBRARY: LibraryAsset[] = manifest as LibraryAsset[];

/** Friendly tab names; unknown categories fall back to a title-cased slug. */
const CATEGORY_LABELS: Record<string, string> = {
  "app-screens": "App screens",
  mascots: "Illustrations",
  misc: "Other",
};

/** Tabs in this order first; any new folder appears after them. */
const CATEGORY_ORDER = ["app-screens", "mascots", "misc"];

export function categoryLabel(category: string): string {
  return (
    CATEGORY_LABELS[category] ??
    category.replace(/-/g, " ").replace(/^\w/, (c) => c.toUpperCase())
  );
}

export function libraryCategories(): string[] {
  const present = [...new Set(LIBRARY.map((a) => a.category))];
  return present.sort((a, b) => {
    const ia = CATEGORY_ORDER.indexOf(a);
    const ib = CATEGORY_ORDER.indexOf(b);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib) || a.localeCompare(b);
  });
}

/** Fetch a library asset as a File so it can go through the normal upload paths. */
export async function libraryAssetToFile(asset: LibraryAsset): Promise<File> {
  const res = await fetch(asset.src);
  if (!res.ok) throw new Error(`Couldn't load "${asset.name}" (${res.status}).`);
  const blob = await res.blob();
  const fileName = `${asset.id.split("/").pop()}.webp`;
  return new File([blob], fileName, { type: blob.type || "image/webp" });
}
